void Rules::playerDisconnected(std::int64_t id){using namespace rule;auto*a=state_.actor("player",id);if(a){if(a->get("participating").truth(true))participants_[{"player",id}]=*a;a->object["connected"]=boolean(false);}clearPlayerOperations(id);++state_.state_revision;abandonIfEmpty();}
