void Rules::abandonIfEmpty(){using namespace rule;if(state_.phase!="battle"||!null(state_.battle_result))return;for(const auto&player:state_.players)if(player.second.get("connected").truth(true)&&player.second.get("participating").truth(true)){maybeFinish();return;}for(int team=1;team<=2;++team)if(intField(state_.rules.get("bases").get(std::to_string(team)),"points")>=100){finish(3-team,"base captured",team);return;}maybeFinish();if(!null(state_.battle_result))return;std::int64_t living[3]={},health[3]={},maximum[3]={};for(const auto&identity:rows(state_.bot_manifest)){const auto team=intField(identity,"team");if(team!=1&&team!=2)continue;const auto id=intField(identity,"id");const auto*state=state_.actor("bot",id);const auto&actor=state?*state:identity;const auto max=std::max<std::int64_t>(1,intField(identity,"max_health",1)),hp=std::clamp<std::int64_t>(intField(actor,"health"),0,max);const bool live=actor.get("alive").truth(hp>0)&&hp>0;living[team]+=live?1:0;health[team]+=live?hp:0;maximum[team]+=max;}int winner=0;if(living[1]!=living[2])winner=living[1]>living[2]?1:2;else if(maximum[1]>0&&maximum[2]>0&&health[1]*maximum[2]!=health[2]*maximum[1])winner=health[1]*maximum[2]>health[2]*maximum[1]?1:2;else if(health[1]!=health[2])winner=health[1]>health[2]?1:2;else winner=state_.round_id%2==0?1:2;finish(winner,"team_eliminated");}
